258	    /**
259	     * Return {@code true} if the supplied Collection is {@code null} or empty.
260	     * Otherwise, return {@code false}.
261	     *
262	     * @param collection the Collection to check
263	     * @return whether the given Collection is empty
264	     */
265	    public static boolean isEmpty(Collection<?> collection) {
266	        return collection == null || collection.isEmpty();
267	    }
268	
269	    /**
270	     * Return {@code true} if the supplied Collection is {@code not null} or not empty.
271	     * Otherwise, return {@code false}.
272	     *
273	     * @param collection the Collection to check
274	     * @return whether the given Collection is not empty
275	     */
276	    public static boolean isNotEmpty(Collection<?> collection) {
277	        return !isEmpty(collection);
278	    }
279	
280	    /**
281	     * Return {@code true} if the supplied Map is {@code null} or empty.
282	     * Otherwise, return {@code false}.
283	     *
284	     * @param map the Map to check
285	     * @return whether the given Map is empty
286	     */
287	    public static boolean isEmptyMap(Map map) {
288	        return map == null || map.isEmpty();
289	    }
290	
291	    /**
292	     * Return {@code true} if the supplied Map is {@code not null} or not empty.
293	     * Otherwise, return {@code false}.
294	     *
295	     * @param map the Map to check
296	     * @return whether the given Map is not empty
297	     */
298	    public static boolean isNotEmptyMap(Map map) {
299	        return !isEmptyMap(map);
300	    }
