302	    /**
303	     * Convert to multiple values to be {@link LinkedHashSet}
304	     *
305	     * @param values one or more values
306	     * @param <T>    the type of <code>values</code>
307	     * @return read-only {@link Set}
308	     */
309	    public static <T> Set<T> ofSet(T... values) {
310	        int size = values == null ? 0 : values.length;
311	        if (size < 1) {
312	            return emptySet();
313	        }
314	
315	        float loadFactor = 1f / ((size + 1) * 1.0f);
316	
317	        if (loadFactor > 0.75f) {
318	            loadFactor = 0.75f;
319	        }
320	
321	        Set<T> elements = new LinkedHashSet<>(size, loadFactor);
322	        for (int i = 0; i < size; i++) {
323	            elements.add(values[i]);
324	        }
325	        return unmodifiableSet(elements);
326	    }
327	
328	    /**
329	     * Get the size of the specified {@link Collection}
330	     *
331	     * @param collection the specified {@link Collection}
332	     * @return must be positive number
333	     * @since 2.7.6
334	     */
335	    public static int size(Collection<?> collection) {
336	        return collection == null ? 0 : collection.size();
337	    }
338	
339	    /**
340	     * Compares the specified collection with another, the main implementation references
341	     * {@link AbstractSet}
342	     *
343	     * @param one     {@link Collection}
344	     * @param another {@link Collection}
345	     * @return if equals, return <code>true</code>, or <code>false</code>
346	     * @since 2.7.6
347	     */
348	    public static boolean equals(Collection<?> one, Collection<?> another) {
349	
350	        if (one == another) {
351	            return true;
352	        }
353	
354	        if (isEmpty(one) && isEmpty(another)) {
355	            return true;
356	        }
357	
358	        if (size(one) != size(another)) {
359	            return false;
360	        }
361	
362	        try {
363	            return one.containsAll(another);
364	        } catch (ClassCastException | NullPointerException unused) {
365	            return false;
366	        }
367	    }
368	
369	    /**
370	     * Add the multiple values into {@link Collection the specified collection}
371	     *
372	     * @param collection {@link Collection the specified collection}
373	     * @param values     the multiple values
374	     * @param <T>        the type of values
375	     * @return the effected count after added
376	     * @since 2.7.6
377	     */
378	    public static <T> int addAll(Collection<T> collection, T... values) {
379	
380	        int size = values == null ? 0 : values.length;
381	
382	        if (collection == null || size < 1) {
383	            return 0;
384	        }
385	
386	        int effectedCount = 0;
387	        for (int i = 0; i < size; i++) {
388	            if (collection.add(values[i])) {
389	                effectedCount++;
390	            }
391	        }
392	
393	        return effectedCount;
394	    }
395	
396	    /**
397	     * Take the first element from the specified collection
398	     *
399	     * @param values the collection object
400	     * @param <T>    the type of element of collection
401	     * @return if found, return the first one, or <code>null</code>
402	     * @since 2.7.6
403	     */
404	    public static <T> T first(Collection<T> values) {
405	        if (isEmpty(values)) {
406	            return null;
407	        }
408	        if (values instanceof List) {
409	            return ((List<T>) values).get(0);
410	        } else {
411	            return values.iterator().next();
412	        }
413	    }
414	
415	    public static <T> T first(List<T> values) {
416	        if (isEmpty(values)) {
417	            return null;
418	        }
419	        return values.get(0);
420	    }
421	
422	    public static <T extends Comparable<? super T>> Set<T> toTreeSet(Set<T> set) {
423	        if (isEmpty(set)) {
424	            return set;
425	        }
426	        if (!(set instanceof TreeSet)) {
427	            set = new TreeSet<>(set);
428	        }
429	        return set;
430	    }
431	
432	    public static <T> Set<T> toTreeSet(Set<T> set, Comparator<? super T> comparator) {
433	        if (set == null) {
434	            return set;
435	        }
436	        Set<T> treeSet = new TreeSet<>(comparator);
437	        treeSet.addAll(set);
438	        return treeSet;
439	    }
440	
441	    public static <T> Set<T> newHashSet(int expectedSize) {
442	        return new HashSet<>(capacity(expectedSize));
443	    }
444	
445	    public static <T> Set<T> newLinkedHashSet(int expectedSize) {
446	        return new LinkedHashSet<>(capacity(expectedSize));
447	    }
448	
449	    public static <K, T> Map<K, T> newHashMap(int expectedSize) {
450	        return new HashMap<>(capacity(expectedSize));
451	    }
452	
453	    public static <K, T> Map<K, T> newLinkedHashMap(int expectedSize) {
454	        return new LinkedHashMap<>(capacity(expectedSize));
455	    }
456	
457	    public static <K, T> Map<K, T> newConcurrentHashMap(int expectedSize) {
458	        if (JRE.JAVA_8.isCurrentVersion()) {
459	            return new SafeConcurrentHashMap<>(capacity(expectedSize));
460	        }
461	        return new ConcurrentHashMap<>(capacity(expectedSize));
462	    }
463	
464	    public static <K, T> Map<K, T> newConcurrentHashMap() {
465	        if (JRE.JAVA_8.isCurrentVersion()) {
466	            return new SafeConcurrentHashMap<>();
467	        }
468	        return new ConcurrentHashMap<>();
469	    }
470	
471	    public static int capacity(int expectedSize) {
472	        if (expectedSize < 3) {
473	            if (expectedSize < 0) {
474	                throw new IllegalArgumentException("expectedSize cannot be negative but was: " + expectedSize);
475	            }
476	            return expectedSize + 1;
477	        }
478	        if (expectedSize < 1 << (Integer.SIZE - 2)) {
479	            return (int) (expectedSize / 0.75F + 1.0F);
480	        }
481	        return Integer.MAX_VALUE;
482	    }
483	
484	    public static class SafeConcurrentHashMap<K, V> extends ConcurrentHashMap<K, V> {
485	        private static final long serialVersionUID = 1L;
486	
487	        public SafeConcurrentHashMap() {}
488	
489	        public SafeConcurrentHashMap(int initialCapacity) {
490	            super(initialCapacity);
491	        }
492	
493	        public SafeConcurrentHashMap(Map<? extends K, ? extends V> m) {
494	            super(m);
495	        }
496	
497	        @Override
498	        public V computeIfAbsent(K key, Function<? super K, ? extends V> mappingFunction) {
499	            V value = get(key);
500	            if (value != null) {
501	                return value;
502	            }
503	            value = mappingFunction.apply(key);
504	            if (value == null) {
505	                return null;
506	            }
507	            V exists = putIfAbsent(key, value);
508	            if (exists != null) {
509	                return exists;
510	            }
511	            return value;
512	        }
513	    }
514	}
