23	import java.util.concurrent.locks.ReentrantLock;
24	import java.util.function.Function;
25	
26	/**
27	 * A 'least recently used' cache based on LinkedHashMap.
28	 *
29	 * @param <K> key
30	 * @param <V> value
31	 */
32	public class LRUCache<K, V> extends LinkedHashMap<K, V> {
33	
34	    private static final long serialVersionUID = -5167631809472116969L;
35	
36	    private static final float DEFAULT_LOAD_FACTOR = 0.75f;
37	    private static final int DEFAULT_MAX_CAPACITY = 1000;
38	
39	    private final Lock lock = new ReentrantLock();
40	    private volatile int maxCapacity;
41	
42	    public LRUCache() {
43	        this(DEFAULT_MAX_CAPACITY);
44	    }
45	
46	    public LRUCache(int maxCapacity) {
47	        super(16, DEFAULT_LOAD_FACTOR, true);
48	        this.maxCapacity = maxCapacity;
49	    }
50	
51	    @Override
52	    protected boolean removeEldestEntry(java.util.Map.Entry<K, V> eldest) {
53	        return size() > maxCapacity;
54	    }
55	
56	    @Override
57	    public boolean containsKey(Object key) {
58	        lock.lock();
59	        try {
60	            return super.containsKey(key);
61	        } finally {
62	            lock.unlock();
63	        }
64	    }
65	
66	    @Override
67	    public V get(Object key) {
68	        lock.lock();
69	        try {
70	            return super.get(key);
71	        } finally {
72	            lock.unlock();
73	        }
74	    }
75	
76	    @Override
77	    public V put(K key, V value) {
78	        lock.lock();
79	        try {
80	            return super.put(key, value);
81	        } finally {
82	            lock.unlock();
83	        }
84	    }
85	
86	    @Override
87	    public V remove(Object key) {
88	        lock.lock();
89	        try {
90	            return super.remove(key);
91	        } finally {
92	            lock.unlock();
93	        }
94	    }
95	
96	    @Override
97	    public int size() {
98	        lock.lock();
99	        try {
100	            return super.size();
101	        } finally {
102	            lock.unlock();
103	        }
104	    }
105	
106	    @Override
107	    public void clear() {
108	        lock.lock();
109	        try {
110	            super.clear();
111	        } finally {
112	            lock.unlock();
113	        }
114	    }
115	
116	    @Override
117	    public V putIfAbsent(K key, V value) {
118	        lock.lock();
119	        try {
120	            return super.putIfAbsent(key, value);
121	        } finally {
122	            lock.unlock();
123	        }
124	    }
125	
126	    @Override
127	    public V computeIfAbsent(K key, Function<? super K, ? extends V> fn) {
128	        V value = get(key);
129	        if (value == null) {
130	            lock.lock();
131	            try {
132	                return super.computeIfAbsent(key, fn);
133	            } finally {
134	                lock.unlock();
135	            }
136	        }
137	        return value;
138	    }
139	
140	    public void lock() {
141	        lock.lock();
142	    }
143	
144	    public void releaseLock() {
145	        lock.unlock();
146	    }
147	
148	    public int getMaxCapacity() {
149	        return maxCapacity;
150	    }
151	
152	    public void setMaxCapacity(int maxCapacity) {
153	        lock.lock();
154	        try {
155	            this.maxCapacity = maxCapacity;
156	            trimToSize();
157	        } finally {
158	            lock.unlock();
159	        }
160	    }
161	
162	    private void trimToSize() {
163	        while (super.size() > maxCapacity) {
164	            Iterator<Map.Entry<K, V>> it = super.entrySet().iterator();
165	            if (it.hasNext()) {
166	                it.next();
167	                it.remove();
168	            }
169	        }
170	    }
171	}
