17	package org.apache.dubbo.metadata;
18	
19	import org.apache.dubbo.common.cache.FileCacheStore;
20	import org.apache.dubbo.common.cache.FileCacheStoreFactory;
21	import org.apache.dubbo.common.config.ConfigurationUtils;
22	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
23	import org.apache.dubbo.common.logger.LoggerFactory;
24	import org.apache.dubbo.common.resource.Disposable;
25	import org.apache.dubbo.common.utils.JsonUtils;
26	import org.apache.dubbo.common.utils.LRUCache;
27	import org.apache.dubbo.common.utils.NamedThreadFactory;
28	
29	import java.util.Collections;
30	import java.util.HashMap;
31	import java.util.Map;
32	import java.util.concurrent.Executors;
33	import java.util.concurrent.ScheduledExecutorService;
34	import java.util.concurrent.TimeUnit;
35	
36	import static org.apache.dubbo.common.constants.CommonConstants.DEFAULT_SERVER_SHUTDOWN_TIMEOUT;
37	import static org.apache.dubbo.common.constants.LoggerCodeConstants.COMMON_FAILED_LOAD_MAPPING_CACHE;
38	import static org.apache.dubbo.common.constants.LoggerCodeConstants.COMMON_UNEXPECTED_EXCEPTION;
39	
40	public abstract class AbstractCacheManager<V> implements Disposable {
41	    protected final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(getClass());
42	
43	    private ScheduledExecutorService executorService;
44	
45	    protected FileCacheStore cacheStore;
46	    protected LRUCache<String, V> cache;
47	
48	    protected void init(
49	            boolean enableFileCache,
50	            String filePath,
51	            String fileName,
52	            int entrySize,
53	            long fileSize,
54	            int interval,
55	            ScheduledExecutorService executorService) {
56	        this.cache = new LRUCache<>(entrySize);
57	
58	        try {
59	            cacheStore = FileCacheStoreFactory.getInstance(filePath, fileName, enableFileCache);
60	            Map<String, String> properties = cacheStore.loadCache(entrySize);
61	            if (logger.isDebugEnabled()) {
62	                logger.debug("Successfully loaded " + getName() + " cache from file " + fileName + ", entries "
63	                        + properties.size());
64	            }
65	            for (Map.Entry<String, String> entry : properties.entrySet()) {
66	                String key = entry.getKey();
67	                String value = entry.getValue();
68	                V v = toValueType(value);
69	                put(key, v);
70	            }
71	            // executorService can be empty if FileCacheStore fails
72	            if (executorService == null) {
73	                this.executorService = Executors.newSingleThreadScheduledExecutor(
74	                        new NamedThreadFactory("Dubbo-cache-refreshing-scheduler", true));
75	            } else {
76	                this.executorService = executorService;
77	            }
78	
79	            this.executorService.scheduleWithFixedDelay(
80	                    new CacheRefreshTask<>(this.cacheStore, this.cache, this, fileSize),
81	                    10,
82	                    interval,
83	                    TimeUnit.MINUTES);
84	        } catch (Exception e) {
85	            logger.error(COMMON_FAILED_LOAD_MAPPING_CACHE, "", "", "Load mapping from local cache file error ", e);
86	        }
87	    }
88	
89	    protected abstract V toValueType(String value);
90	
91	    protected abstract String getName();
92	
93	    protected boolean validate(String key, V value) {
94	        return value != null;
95	    }
96	
97	    public V get(String key) {
98	        return cache.get(key);
99	    }
100	
101	    public void put(String key, V apps) {
102	        if (validate(key, apps)) {
103	            cache.put(key, apps);
104	        }
105	    }
106	
107	    public V remove(String key) {
108	        return cache.remove(key);
109	    }
110	
111	    public Map<String, V> getAll() {
112	        if (cache.isEmpty()) {
113	            return Collections.emptyMap();
114	        }
115	
116	        Map<String, V> copyMap = new HashMap<>();
117	        cache.lock();
118	        try {
119	            for (Map.Entry<String, V> entry : cache.entrySet()) {
120	                copyMap.put(entry.getKey(), entry.getValue());
121	            }
122	        } finally {
123	            cache.releaseLock();
124	        }
125	        return Collections.unmodifiableMap(copyMap);
126	    }
127	
128	    public void update(Map<String, V> newCache) {
129	        for (Map.Entry<String, V> entry : newCache.entrySet()) {
130	            put(entry.getKey(), entry.getValue());
131	        }
132	    }
133	
134	    public void destroy() {
135	        if (executorService != null) {
136	            executorService.shutdownNow();
137	            try {
138	                if (!executorService.awaitTermination(
139	                        ConfigurationUtils.reCalShutdownTime(DEFAULT_SERVER_SHUTDOWN_TIMEOUT), TimeUnit.MILLISECONDS)) {
140	                    logger.warn(
141	                            COMMON_UNEXPECTED_EXCEPTION, "", "", "Wait global executor service terminated timeout.");
142	                }
143	            } catch (InterruptedException e) {
144	                logger.warn(COMMON_UNEXPECTED_EXCEPTION, "", "", "destroy resources failed: " + e.getMessage(), e);
145	            }
146	        }
147	        if (cacheStore != null) {
148	            cacheStore.destroy();
149	        }
150	        if (cache != null) {
151	            cache.clear();
152	        }
153	    }
154	
155	    public static class CacheRefreshTask<V> implements Runnable {
156	        private final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(getClass());
157	        private static final String DEFAULT_COMMENT = "Dubbo cache";
158	        private final FileCacheStore cacheStore;
159	        private final LRUCache<String, V> cache;
160	        private final AbstractCacheManager<V> cacheManager;
161	        private final long maxFileSize;
162	
163	        public CacheRefreshTask(
164	                FileCacheStore cacheStore,
165	                LRUCache<String, V> cache,
166	                AbstractCacheManager<V> cacheManager,
167	                long maxFileSize) {
168	            this.cacheStore = cacheStore;
169	            this.cache = cache;
170	            this.cacheManager = cacheManager;
171	            this.maxFileSize = maxFileSize;
172	        }
173	
174	        @Override
175	        public void run() {
176	            Map<String, String> properties = new HashMap<>();
177	
178	            cache.lock();
179	            try {
180	                for (Map.Entry<String, V> entry : cache.entrySet()) {
181	                    properties.put(entry.getKey(), JsonUtils.toJson(entry.getValue()));
182	                }
183	            } finally {
184	                cache.releaseLock();
185	            }
186	
187	            if (logger.isDebugEnabled()) {
188	                logger.debug("Dumping " + cacheManager.getName() + " caches, latest entries " + properties.size());
189	            }
190	            cacheStore.refreshCache(properties, DEFAULT_COMMENT, maxFileSize);
191	        }
192	    }
193	
194	    // for test unit
195	    public FileCacheStore getCacheStore() {
196	        return cacheStore;
197	    }
198	
199	    public LRUCache<String, V> getCache() {
200	        return cache;
201	    }
202	}
