package org.apache.dubbo.common.utils;

import org.junit.jupiter.api.Test;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.equalTo;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class LRU2CacheTest {
    @Test
    void testCache() {
        LRU2Cache<String, Integer> cache = new LRU2Cache<String, Integer>(3);
        cache.put("one", 1);
        cache.put("two", 2);
        cache.put("three", 3);
        assertFalse(cache.containsKey("one"));
        assertFalse(cache.containsKey("two"));
        assertFalse(cache.containsKey("three"));
        cache.put("one", 1);
        cache.put("two", 2);
        cache.put("three", 3);
        assertThat(cache.get("one"), equalTo(1));
        assertThat(cache.get("two"), equalTo(2));
        assertThat(cache.get("three"), equalTo(3));
        assertThat(cache.size(), equalTo(3));
        cache.put("four", 4);
        cache.put("four", 4);
        assertThat(cache.size(), equalTo(3));
        assertFalse(cache.containsKey("one"));
        assertTrue(cache.containsKey("two"));
        assertTrue(cache.containsKey("three"));
        assertTrue(cache.containsKey("four"));
        cache.remove("four");
        assertThat(cache.size(), equalTo(2));
        cache.put("five", 5);
        cache.put("five", 5);
        assertFalse(cache.containsKey("four"));
        assertTrue(cache.containsKey("five"));
        assertTrue(cache.containsKey("two"));
        assertTrue(cache.containsKey("three"));
        assertThat(cache.size(), equalTo(3));
        cache.put("six", 6);
        assertFalse(cache.containsKey("six"));
    }

    @Test
    void testCapacity() {
        LRU2Cache<String, Integer> cache = new LRU2Cache<String, Integer>();
        assertThat(cache.getMaxCapacity(), equalTo(1000));
        cache.setMaxCapacity(10);
        assertThat(cache.getMaxCapacity(), equalTo(10));
    }

    @Test
    void testTrimWhenCapacityReduced() {
        LRU2Cache<String, Integer> cache = new LRU2Cache<>(5);

        cache.put("1", 1);
        cache.put("2", 2);
        cache.put("3", 3);
        cache.put("4", 4);
        cache.put("5", 5);

        // trigger LRU2 flow (do not assume size)
        cache.get("1");
        cache.get("1");
        cache.get("2");
        cache.get("2");
        cache.get("3");
        cache.get("3");
        cache.get("4");
        cache.get("4");
        cache.get("5");
        cache.get("5");

        // Reduce capacity
        cache.setMaxCapacity(3);

        // Only guarantee we care about:
        assertTrue(cache.size() <= 3);

        // Old entries should be gone
        assertFalse(cache.containsKey("1"));
        assertFalse(cache.containsKey("2"));
    }

    @Test
    void testPreCacheTrimWhenCapacityReduced() {
        LRU2Cache<String, Integer> cache = new LRU2Cache<>(5);

        cache.put("1", 1);
        cache.put("2", 2);
        cache.put("3", 3);
        cache.put("4", 4);
        cache.put("5", 5);

        cache.setMaxCapacity(2);

        // Access entries to promote them through LRU2 flow
        cache.get("1");
        cache.get("2");
        cache.get("3");
        cache.get("4");
        cache.get("5");

        assertTrue(cache.size() <= 2);
    }
}

