                return value;
            }
        } finally {
            lock.unlock();
        }
    }

    @Override
    public V computeIfAbsent(K key, Function<? super K, ? extends V> fn) {
        V value = get(key);
        if (value == null) {
            value = fn.apply(key);
            put(key, value);
        }
        return value;
    }

